pub struct DebugRenderer {
    context: Context,

    points_occluded: Vec<PointChunk>,
    points_overlay: Vec<PointChunk>,

    lines_occluded: Vec<LineChunk>,
    lines_overlay: Vec<LineChunk>,

    faces_occluded: Vec<FaceChunk>,
    faces_overlay: Vec<FaceChunk>,

    temp_points_occluded: TempPointRenderer,
    temp_points_overlay: TempPointRenderer,

    temp_lines_occluded: TempLineRenderer,
    temp_lines_overlay: TempLineRenderer,

    temp_faces_occluded: TempFaceRenderer,
    temp_faces_overlay: TempFaceRenderer,
}

impl DebugRenderer {
    pub fn new(context: &Context) -> Self {
        Self {
            context: Clone::clone(context),
            points_occluded: Vec::new(),
            points_overlay: Vec::new(),
            lines_occluded: Vec::new(),
            lines_overlay: Vec::new(),
            faces_occluded: Vec::new(),
            faces_overlay: Vec::new(),

            temp_points_occluded: TempPointRenderer::new(context, true),
            temp_points_overlay: TempPointRenderer::new(context, false),
            temp_lines_occluded: TempLineRenderer::new(context, true),
            temp_lines_overlay: TempLineRenderer::new(context, false),
            temp_faces_occluded: TempFaceRenderer::new(context, true),
            temp_faces_overlay: TempFaceRenderer::new(context, false),
        }
    }

    pub fn clear(&mut self) {
        self.points_occluded.clear();
        self.points_overlay.clear();
        self.lines_occluded.clear();
        self.lines_overlay.clear();
        self.faces_occluded.clear();
        self.faces_overlay.clear();
    }

    pub fn temp_point(&mut self, position: Vec3, radius: f32, color: Srgba, depth: bool) {
        let t = if depth {
            &mut self.temp_points_occluded
        } else {
            &mut self.temp_points_overlay
        };

        t.instances.push(PointInstance { position, radius, color });
    }

    pub fn temp_edge(&mut self, a: Vec3, b: Vec3, thickness: f32, color: Srgba, depth: bool) {
        let t = if depth {
            &mut self.temp_lines_occluded
        } else {
            &mut self.temp_lines_overlay
        };

        t.instances.push(LineInstance { a, b, thickness, color });
    }

    pub fn temp_face(&mut self, a: Vec3, b: Vec3, c: Vec3, color: Srgba, depth: bool) {
        let t = if depth {
            &mut self.temp_faces_occluded
        } else {
            &mut self.temp_faces_overlay
        };

        t.instances.push(FaceInstance { a, b, c, color });
    }

    pub fn clear_temp_points(&mut self) {
        self.temp_points_occluded.instances.clear();
        self.temp_points_overlay.instances.clear();
    }

    pub fn clear_temp_edges(&mut self) {
        self.temp_lines_occluded.instances.clear();
        self.temp_lines_overlay.instances.clear();
    }

    pub fn clear_temp_faces(&mut self) {
        self.temp_faces_occluded.instances.clear();
        self.temp_faces_overlay.instances.clear();
    }
    
    /* ============================================================
    POINTS
    ============================================================ */
    
    pub fn point(&mut self, position: Vec3, radius: f32, color: Srgba, depth: bool) {
        let chunks = if depth {
            &mut self.points_occluded
        } else {
            &mut self.points_overlay
        };

        if chunks.is_empty() || chunks.last().unwrap().instances.len() >= CHUNK_SIZE {
            chunks.push(PointChunk::new(&self.context, depth));
        }

        let chunk = chunks.last_mut().unwrap();

        chunk.instances.push(PointInstance {
            position,
            radius,
            color,
        });

        chunk.dirty = true;
    }

    /* ============================================================
       LINES
    ============================================================ */

    pub fn edge(&mut self, a: Vec3, b: Vec3, thickness: f32, color: Srgba, depth: bool) {
        let chunks = if depth {
            &mut self.lines_occluded
        } else {
            &mut self.lines_overlay
        };

        if chunks.is_empty() || chunks.last().unwrap().instances.len() >= CHUNK_SIZE {
            chunks.push(LineChunk::new(&self.context, depth));
        }
        
        let chunk = chunks.last_mut().unwrap();
        
        chunk.instances.push(LineInstance {
            a,
            b,
            thickness,
            color,
        });

        chunk.dirty = true;
    }

    pub fn face(&mut self, a: Vec3, b: Vec3, c: Vec3, color: Srgba, depth: bool) {
        let chunks = if depth {
            &mut self.faces_occluded
        } else {
            &mut self.faces_overlay
        };

        if chunks.is_empty() || chunks.last().unwrap().instances.len() >= CHUNK_SIZE {
            chunks.push(FaceChunk::new(&self.context, depth));
        }
        
        let chunk = chunks.last_mut().unwrap();

        chunk.instances.push(FaceInstance { a, b, c, color });
        chunk.dirty = true;
    }

    /* ============================================================
       GPU UPLOAD
       ============================================================ */
       
       pub fn upload(&mut self) {
           for c in &mut self.points_occluded {
            c.upload(&self.context);
        }
        for c in &mut self.points_overlay {
            c.upload(&self.context);
        }
        for c in &mut self.lines_occluded {
            c.upload(&self.context);
        }
        for c in &mut self.lines_overlay {
            c.upload(&self.context);
        }
        for c in &mut self.faces_occluded {
            c.upload(&self.context);
        }
        for c in &mut self.faces_overlay {
            c.upload(&self.context);
        }

        self.temp_points_occluded.upload();
        self.temp_points_overlay.upload();

        self.temp_lines_occluded.upload();
        self.temp_lines_overlay.upload();

        self.temp_faces_occluded.upload();
        self.temp_faces_overlay.upload();
    }

    /* ============================================================
       RENDER STREAMS
    ============================================================ */

    pub fn occluded(&self) -> impl Iterator<Item = &dyn Object> {
        self.points_occluded
            .iter()
            .map(|c| &c.mesh as &dyn Object)
            .chain(self.lines_occluded.iter().map(|c| &c.mesh as &dyn Object))
            .chain(self.faces_occluded.iter().map(|c| &c.mesh as &dyn Object))
            .chain(std::iter::once(&self.temp_points_occluded.mesh as &dyn Object))
            .chain(std::iter::once(&self.temp_lines_occluded.mesh as &dyn Object))
            .chain(std::iter::once(&self.temp_faces_occluded.mesh as &dyn Object))
    }

    pub fn overlay(&self) -> impl Iterator<Item = &dyn Object> {
        self.points_overlay
        .iter()
        .map(|c| &c.mesh as &dyn Object)
            .chain(self.lines_overlay.iter().map(|c| &c.mesh as &dyn Object))
            .chain(self.faces_overlay.iter().map(|c| &c.mesh as &dyn Object))
            .chain(std::iter::once(&self.temp_points_overlay.mesh as &dyn Object))
            .chain(std::iter::once(&self.temp_lines_overlay.mesh as &dyn Object))
            .chain(std::iter::once(&self.temp_faces_overlay.mesh as &dyn Object))
    }
}

