struct LineInstance {
    a: Vec3,
    b: Vec3,
    thickness: f32,
    color: Srgba,
}

struct LineChunk {
    instances: Vec<LineInstance>,
    mesh: Gm<InstancedMesh, ColorMaterial>,
    dirty: bool,
}

impl LineChunk {
    fn new(context: &Context, depth: bool) -> Self {
        let cpu = CpuMesh::cylinder(8);

        let mesh = Gm::new(
            InstancedMesh::new(context, &Instances::default(), &cpu),
            ColorMaterial {
                color: Srgba::WHITE,
                render_states: RenderStates {
                    depth_test: if depth {
                        DepthTest::Less
                    } else {
                        DepthTest::Always
                    },
                    cull: Cull::None,
                    ..Default::default()
                },
                ..Default::default()
            },
        );

        Self {
            instances: Vec::new(),
            mesh,
            dirty: true,
        }
    }

    fn upload(&mut self, _context: &Context) {
        if !self.dirty {
            return;
        }

        let mut transforms = Vec::with_capacity(self.instances.len());
        let mut colors = Vec::with_capacity(self.instances.len());

        for i in &self.instances {
            let dir = i.b - i.a;
            let len = dir.magnitude();

            if len < 1e-6 {
                continue;
            }

            let dir_norm = dir / len;

            // three-d cylinder is Z-axis aligned – rotate Z to the edge direction,
            // using the horizontal perpendicular as the fallback to keep the
            // thickness directions horizontal (Y or X will align with horiz_perp).
            let rotation = Quaternion::from_arc(Vec3::unit_x(), dir_norm, None);

            // Scale: X and Y are the radius (thickness), Z is the length
            let transform =
                Mat4::from_translation(i.a)
                * Mat4::from(rotation)
                * Mat4::from_nonuniform_scale(
                    len,           // X → now aligned to the edge
                    i.thickness,   // Y
                    i.thickness,   // Z
                )
                ;
                
            transforms.push(transform);
            colors.push(i.color);
        }

        let instances = Instances {
            transformations: transforms,
            colors: Some(colors),
            texture_transformations: None,
        };

        self.mesh.geometry.set_instances(&instances);
        self.dirty = false;
    }
}

struct FaceInstance {
    a: Vec3,
    b: Vec3,
    c: Vec3,
    color: Srgba,
}

struct FaceChunk {
    instances: Vec<FaceInstance>,
    mesh: Gm<InstancedMesh, ColorMaterial>,
    dirty: bool,
}

impl FaceChunk {
    fn new(context: &Context, depth: bool) -> Self {
        let cpu = CpuMesh {
            positions: Positions::F32(vec![
                Vec3::new(0.0, 0.0, 0.0),
                Vec3::new(1.0, 0.0, 0.0),
                Vec3::new(0.0, 1.0, 0.0),
            ]),
            indices: Indices::U32(vec![0, 1, 2]),
            normals: None,
            tangents: None,
            uvs: None,
            colors: None,
        };

        let mesh = Gm::new(
            InstancedMesh::new(context, &Instances::default(), &cpu),
            ColorMaterial {
                color: Srgba::WHITE,
                render_states: RenderStates {
                    depth_test: if depth {
                        DepthTest::LessOrEqual
                    } else {
                        DepthTest::Always
                    },
                    cull: Cull::None,
                    ..Default::default()
                },
                ..Default::default()
            },
        );

        Self {
            instances: Vec::new(),
            mesh,
            dirty: true,
        }
    }

    fn upload(&mut self, _context: &Context) {
        if !self.dirty {
            return;
        }

        let mut transforms = Vec::new();
        let mut colors = Vec::new();

        for i in &self.instances {
            let a = i.a;
            let b = i.b;
            let c = i.c;

            let ab = b - a;
            let ac = c - a;

            let normal = ab.cross(ac);
            let n_len = normal.magnitude();

            if n_len < 1e-8 {
                continue;
            }

            let n = normal / n_len;

            // -------------------------
            // LIGHTING (per instance)
            // -------------------------
            let brightness = (n.dot(LIGHT_DIR) * 0.45 + 0.55)
                .sqrt()
                .clamp(0.0, 1.0);

            let shade = (brightness * 255.0) as u8;

            let final_color = Srgba::new(
                (i.color.r as u16 * shade as u16 / 255) as u8,
                (i.color.g as u16 * shade as u16 / 255) as u8,
                (i.color.b as u16 * shade as u16 / 255) as u8,
                i.color.a,
            );

            // -------------------------
            // TRANSFORM
            // -------------------------
            let transform =
                Mat4::from_translation(a)
                * Mat4::from(Mat3::from_cols(ab, ac, Vec3::unit_z()));

            transforms.push(transform);
            colors.push(final_color);
        }

        self.mesh.geometry.set_instances(&Instances {
            transformations: transforms,
            colors: Some(colors),
            texture_transformations: None,
        });

        self.dirty = false;
    }
}